        field_2 = codepoint >> 10;
        field_1 = (codepoint >> 5) & 0x1F;
        field_0 = (codepoint >> 3) & 0x3;
        offset = codepoint & 0x7;

        v = UppercaseTable1[(int)field_2];
        v = UppercaseTable2[(int)((v << 5) | field_1)];
        v = UppercaseTable3[(int)((v << 2) | field_0)];

        return (v >> (int)offset) & 0x1;
    }

